-- Aurora colour scheme for Neovim · generated by matugen from your wallpaper (see ~/.config/matugen)
-- edits get overwritten · open editors reload it on every wallpaper change
local ok, base16 = pcall(require, "mini.base16")
if not ok then
  vim.notify("aurora: mini.base16 isn't installed yet (restart nvim once)", vim.log.levels.WARN)
  return
end

local p = {
  bg      = "{{colors.surface_container_lowest.default.hex}}",
  bg1     = "{{colors.surface_container_low.default.hex}}",
  bg2     = "{{colors.surface_container.default.hex}}",
  bg3     = "{{colors.surface_container_high.default.hex}}",
  fg      = "{{colors.on_surface.default.hex}}",
  fg2     = "{{colors.on_surface_variant.default.hex}}",
  muted   = "{{colors.outline.default.hex}}",
  dim     = "{{colors.outline_variant.default.hex}}",
  primary = "{{colors.primary.default.hex}}",
  second  = "{{colors.secondary.default.hex}}",
  third   = "{{colors.tertiary.default.hex}}",
  onprim  = "{{colors.on_primary.default.hex}}",
  error   = "{{colors.error.default.hex}}",
  -- fixed accents (same as kitty / VS Code) so code stays readable on one-colour wallpapers
  yellow  = "#f5d58a",
  pink    = "#f9a8d4",
  green   = "#6ee7c8",
}

base16.setup({
  palette = {
    base00 = p.bg,      -- background
    base01 = p.bg1,     -- lighter background (status line, line numbers bg)
    base02 = p.bg3,     -- selection
    base03 = p.muted,   -- comments
    base04 = p.fg2,     -- dark foreground (status bars)
    base05 = p.fg,      -- default foreground
    base06 = p.fg,      -- light foreground
    base07 = p.fg,      -- lightest
    base08 = p.error,   -- variables / tags / errors
    base09 = p.pink,    -- numbers, constants
    base0A = p.third,   -- types, classes
    base0B = p.yellow,  -- strings
    base0C = p.second,  -- regex, escapes, support
    base0D = p.second,  -- functions
    base0E = p.primary, -- keywords
    base0F = p.dim,     -- deprecated, delimiters
  },
  use_cterm = true,
})

vim.g.colors_name = "aurora"

-- a few touches on top of base16
local hl = function(g, o) vim.api.nvim_set_hl(0, g, o) end
hl("CursorLine",      { bg = p.bg1 })
hl("CursorLineNr",    { fg = p.primary, bold = true })
hl("LineNr",          { fg = p.dim })
hl("Visual",          { bg = p.bg3 })
hl("NormalFloat",     { fg = p.fg, bg = p.bg1 })
hl("FloatBorder",     { fg = p.dim, bg = p.bg1 })
hl("FloatTitle",      { fg = p.primary, bg = p.bg1, bold = true })
hl("Pmenu",           { fg = p.fg, bg = p.bg1 })
hl("PmenuSel",        { fg = p.onprim, bg = p.primary, bold = true })
hl("WinSeparator",    { fg = p.bg3 })
hl("Search",          { fg = p.bg, bg = p.yellow })
hl("IncSearch",       { fg = p.bg, bg = p.primary })
hl("MatchParen",      { fg = p.primary, bold = true, underline = true })
hl("Comment",         { fg = p.muted, italic = true })
hl("@comment",        { link = "Comment" })
hl("@keyword",        { fg = p.primary })
hl("@keyword.return", { fg = p.primary, italic = true })
hl("@function",       { fg = p.second })
hl("@function.call",  { fg = p.second })
hl("@type",           { fg = p.third })
hl("@string",         { fg = p.yellow })
hl("@number",         { fg = p.pink })
hl("@boolean",        { fg = p.pink })
hl("@variable",       { fg = p.fg })
hl("@variable.member",{ fg = p.fg2 })
hl("@property",       { fg = p.fg2 })
hl("@punctuation",    { fg = p.muted })
hl("DiagnosticError", { fg = p.error })
hl("DiagnosticWarn",  { fg = p.yellow })
hl("DiagnosticInfo",  { fg = p.second })
hl("DiagnosticHint",  { fg = p.third })
hl("DiagnosticOk",    { fg = p.green })
hl("GitSignsAdd",     { fg = p.green })
hl("GitSignsChange",  { fg = p.second })
hl("GitSignsDelete",  { fg = p.error })
hl("SnacksDashboardHeader", { fg = p.primary })
hl("SnacksDashboardKey",    { fg = p.third })
hl("SnacksPickerMatch",     { fg = p.primary, bold = true })
hl("WhichKey",        { fg = p.primary })
hl("WhichKeyGroup",   { fg = p.third })
hl("WhichKeyDesc",    { fg = p.fg2 })
